const p = JSON.parse($input.first().json.input || '{}');
const auth = 'Basic ' + Buffer.from($env.WOO_CONSUMER_KEY + ':' + $env.WOO_CONSUMER_SECRET).toString('base64');
const qsParams = { status: 'publish', stock_status: 'instock', per_page: '10' };
if (p.query) qsParams.search = p.query;
const qs = Object.entries(qsParams).map(([k,v]) => encodeURIComponent(k)+'='+encodeURIComponent(v)).join('&');

const respData = await $helpers.httpRequest({
  method: 'GET',
  url: $env.WOO_BASE_URL + '/wp-json/wc/v3/products?' + qs,
  headers: { Authorization: auth }
});

const money = n => '$' + Number(n || 0).toLocaleString('es-CO');

let lista = Array.isArray(respData) ? respData : [];
// Excluir agotados aunque WC los marque stock_status=instock con stock_quantity 0
lista = lista.filter(r => (r.stock_quantity == null) ? r.stock_status === 'instock' : Number(r.stock_quantity) > 0);
if (p.linea) lista = lista.filter(r => r.tags && r.tags.some(t => t.name && t.name.toLowerCase().includes(p.linea.toLowerCase())));
if (p.talla) {
  const tm = p.talla.toUpperCase();
  lista = lista.filter(r => (r.attributes || []).some(a => ['talla','size'].includes((a.name||'').toLowerCase()) && a.options && a.options.map(s => s.toUpperCase()).includes(tm)));
}
if (p.categoria) lista = lista.filter(r => r.categories && r.categories.some(c => c.name && c.name.toLowerCase().includes(p.categoria.toLowerCase())));
lista = lista.slice(0, 10);
if (!lista.length) return [{ json: { sin_resultados: true } }];

return lista.map(r => {
  const regular = Number(r.regular_price) || 0;
  const actual = Number(r.price) || 0;
  const sale = Number(r.sale_price) || actual;
  const enOferta = r.on_sale === true && regular > 0 && sale > 0 && sale < regular;
  const descPct = enOferta ? Math.round((1 - sale/regular) * 100) : 0;
  const precioDisplay = enOferta
    ? 'antes ' + money(regular) + ' ahora ' + money(sale) + ' (' + descPct + '% OFF)'
    : money(actual);
  return { json: {
    woo_product_id: r.id,
    nombre: r.name,
    precio_cop: r.price,
    precio_display: precioDisplay,
    descuento_pct: descPct,
    en_oferta: enOferta,
    precio_regular: regular || null,
    precio_oferta: enOferta ? sale : null,
    oferta_hasta: r.date_on_sale_to || null,
    tallas_disponibles: ((r.attributes || []).find(a => ['talla','size'].includes((a.name||'').toLowerCase())) || {}).options || [],
    descripcion_corta: (r.short_description || '').replace(/<[^>]+>/g, '').trim().substring(0, 200),
    url_imagen: r.images && r.images[0] ? r.images[0].src : null,
    hay_variaciones: (r.variations || []).length > 0,
    woo_variation_ids: r.variations || []
  } };
});

